import { readFileSync } from "node:fs";

const PKCS8_HEADER = "@@PEM_BEGIN@@PRIVATE KEY-----";

export function loadKey(path: string): string {
  const pem = readFileSync(path, "utf8").trim();
  if (!pem.startsWith(PKCS8_HEADER)) {
    throw new Error(`${path}: expected a PKCS#8 key, run: openssl pkcs8 -topk8 -nocrypt -in key.pem`);
  }
  return pem;
}

